def send_email_with_default_template(subject, receivers=None, cc=None, sender='taf.krkpz@nokia.com',
                                     additional_info='', files=None, add_team_email=True,
                                     regards="KRK TAG Team", email_builder=None):
    """
    Send e-mail with default template contains basic information about test case.
    eg:

        TEST_SUITE        /home/ute/MN/UTE/robotws/testsuite/Krakow/OAM/regression/UUF/General_UUF.robot
        TEST_NAME         None
        TESTLINE          7_7_UTE5GCLOUDT1SK054 [OMNIA|SCOUT]
        TESTLINE_OWNER    Maciej Kajda
        TEAM              MN RAN RD VRF KRK 1
        VM_FQDN           7-7-UTE5GCLOUDT1SK054.p01.ska-lab.nsn-rdnet.net
        VNC_PASSWORD      c0d5W_!642VQ
        CM_EXECUTION      LINK

    :param subject:             subject
    :param receivers:           list of emails in To filed
    :param cc:                  list of emails in CC field
    :param sender:              sender
    :param additional_info:     additional info added to basic message(html format)
    :param files:               list of path to files
    :param add_team_email:      add team email to CC
    :param regards:             regards
    :param email_builder:       instance of EmailBuilder or None
    :return:
    """

    emb = email_builder if isinstance(email_builder, EmailBuilder) else EmailBuilder()
    html_body = emb.build_default_html_template(additional_info=additional_info, regards=regards)

    if receivers is None:
        receivers = get_builtin_value('EMAIL_RECIPIENTS') or []
    if receivers and not isinstance(receivers, list):
        receivers = receivers.split(',')
    if emb.tl_owner_email:
        receivers.insert(0, emb.tl_owner_email)
    if add_team_email and emb.tl_owner_team_email:
        cc = cc.append(emb.tl_owner_team_email) if cc else [emb.tl_owner_team_email]
        cc = _validate_email(cc)

    if receivers:
        receivers = _validate_email(receivers)
    else:
        logging.warning("No receivers provided. Please fill email address in scout or "
                        "set EMAIL_RECIPIENTS variable directly")
        receivers = ['tomasz.krol@nokia.com']

    send_email(subject=subject, sender=sender, receivers=receivers, cc_receivers=cc, html_body=html_body, files=files)


def send_email(subject, sender, receivers, cc_receivers=None, html_body=None, body=None, files=None):
    """
    Send an email using the SMTP protocol.
    :param subject: Subject of the email
    :param sender: Sender's email address
    :param receivers: List of recipient email addresses
    :param cc_receivers: List of CC recipient email addresses
    :param html_body: HTML body of the email
    :param body: Plain text body of the email
    :param files: List of file paths to attach to the email
    :return: None
    """
    msg = Message(
        From=sender,
        To=receivers,
        CC=cc_receivers,
        Subject=subject,
        Html=html_body,
        Body=body,
        attachments=files,
        charset="utf-8")

    server = smtplib.SMTP(host='mailrelay.int.nokia.com', port=25)
    to = [msg.To] if isinstance(msg.To, str) else msg.To
    if msg.CC:
        cc = [msg.CC] if isinstance(msg.CC, str) else msg.CC
        to = to + cc
    server.sendmail(from_addr=msg.From,
                    to_addrs=to,
                    msg=msg.as_string())

    server.quit()


def _validate_email(emails):
    allowed_domains = ["@nokia.com", "@internal.nsn.com"]
    emails = set(emails)
    valid_emails = {mail.lstrip() for mail in emails if any(domain in mail for domain in allowed_domains)}
    invalid_emails = emails - valid_emails
    if invalid_emails:
        logging.debug(f"Emails not supported: {','.join(invalid_emails)}")
    return list(valid_emails)


class EmailBuilder:
    def __init__(self, tl_name=None, tl_owner_email=None, tl_owner_name=None,
                 tl_owner_team=None, tl_owner_team_email=None, scout_bts_name=None):
        self.tl_name = tl_name or get_testline_name()
        self.scout_bts_name = scout_bts_name
        self.suite_name = get_builtin_value('SUITE SOURCE')
        self.test_case = get_builtin_value(param_name="TEST NAME")
        self.cm_execution_link = os.environ.get("CM_EXECUTION_LINK")
        vm_fqdn = safe_call(get_vm_fqdn)
        self.vm_fqdn = vm_fqdn if vm_fqdn and vm_fqdn != "Host" else ""
        self.vm_hostname = safe_call(get_vm_hostname)
        self.vm_ip_address = safe_call(get_vm_ip_address)
        self.vnc_password = safe_call(get_vm_vnc_password)

        self.tl_details = self._get_tl_details_from_scout_and_omnia()

        self.tl_owner_email = tl_owner_email or self.tl_details['owner_email']
        self.tl_owner_name = tl_owner_name or self.tl_details['owner_name']
        self.tl_owner_team = tl_owner_team or self.tl_details['team_name']
        self.tl_owner_team_email = tl_owner_team_email or self.tl_details['team_email']

    def build_default_html_template(self, additional_info='', regards="KRK TAG Team"):
        basic_info = {
            'TEST_SUITE': self.suite_name,
            'TEST_NAME': self.test_case,
            'TESTLINE': f"{self.tl_name} {self._build_hyper_link_to_omnia_and_scout()}",
            'TESTLINE_OWNER': self.tl_owner_name,
            'TEAM': self.tl_owner_team,
            'VM_HOSTNAME': self.vm_hostname,
        }
        if self.vm_fqdn:
            basic_info['VM_FQDN'] = self.vm_fqdn
        else:
            basic_info['VM_IP_ADDRESS'] = self.vm_ip_address

        if self.cm_execution_link:
            basic_info['VNC_PASSWORD'] = self.vnc_password
            basic_info['CM_EXECUTION'] = "<a href='{}'>LINK</a>".format(self.cm_execution_link)

        basic_info_html = ""
        for name, value in basic_info.items():
            basic_info_html = basic_info_html + "{:<18}{}\n".format(name, value)
        basic_info_html = "<pre>{}</pre>".format(basic_info_html)
        msg_content = r"""
        <html>
            <body>
                <b>TEST CASE DETAILS:</b>
                <hr color="black">
                <br>
                {basic_info}
                <br>
                <hr color="black">
                <br>
                {additional_info}
                <p>Regards<br> {regards} </p>
            </body>
        </html>
        """.format(basic_info=basic_info_html, additional_info=additional_info, regards=regards)

        return msg_content

    def _get_tl_details_from_omnia(self):
        tl_owner_info = {}
        scout_bts_names = []
        try:
            tl_owner_info = get_testline_owner_info_from_omnia(testline=self.tl_name)
            scout_bts_names = get_scout_bts_names_for_testline(testline=self.tl_name)
            logging.debug("Info from OMNIA: {}".format(tl_owner_info))
            logging.debug("Scout BTS names: {}".format(scout_bts_names))
        except IndexError as e:
            logging.info("Cannot get info from OMNIA - most probably testline is not defined in OMNIA")
            logging.debug("\tException: {}".format(repr(e)))
        except ConnectTimeout as e:
            logging.warning("Unable to connect to OMNIA. Check if the firewall allows access "
                            "to https://omnia.krk-lab.nsn-rdnet.net/. If not, please open FW ticket to your subnet")
            logging.debug("\tException: {}".format(repr(e)))
        except Exception as e:
            logging.info("Other exception while getting info from OMNIA")
            logging.debug("\tException: {}".format(repr(e)))

        return tl_owner_info, scout_bts_names

    def _get_bts_details_from_scout(self):
        tl_scout_info = {}
        try:
            tl_scout_info = GenericScout.get_testline_owner_info_from_scout(testline_name=self.scout_bts_name)
            logging.debug("Info from SCOUT: {}".format(tl_scout_info))
        except Exception as e:
            logging.debug("Cannot get info from scout")
            logging.debug("Exception: {}".format(repr(e)))
        return tl_scout_info

    def _get_tl_details_from_scout_and_omnia(self):
        tl_details = dict.fromkeys(['owner_email', 'owner_name', 'team_name', 'team_email',
                                    'omnia_link', 'scout_link'], '')
        if self.scout_bts_name is None:
            omnia_owner_info, scout_bts_names = self._get_tl_details_from_omnia()
            self.scout_bts_name = safe_call(self._get_proper_scout_bts_name, scout_bts_names=scout_bts_names,
                                            log_warn=False)
            logging.debug("Selected SCOUT BTS name: {}".format(self.scout_bts_name))

        else:
            omnia_owner_info = {'link': get_link_to_omnia_testline(self.tl_name)}

        scout_owner_info = self._get_bts_details_from_scout()
        if self.scout_bts_name and not scout_owner_info:
            _omnia_owner_info, _ = self._get_tl_details_from_omnia()
            omnia_owner_info.update(_omnia_owner_info)

        for param in tl_details:
            omnia_value = omnia_owner_info.get(param)
            scout_value = scout_owner_info.get(param)
            final_value = omnia_value or scout_value
            if param == 'scout_link':
                final_value = scout_owner_info.get("link")
            elif param == 'omnia_link':
                final_value = omnia_owner_info.get("link")
            tl_details[param] = final_value

        return tl_details

    def _get_proper_scout_bts_name(self, scout_bts_names):
        scout_bts_name = scout_bts_names[0] if scout_bts_names else self.tl_name
        if GenericScout.is_bts_defined_in_scout(scout_bts_name):
            return scout_bts_name
        else:
            scout_bts_name_multi = f"{scout_bts_name}_1"
            logging.debug(f"BTS name {scout_bts_name} is not defined in SCOUT. Trying {scout_bts_name_multi} name.")
            if GenericScout.is_bts_defined_in_scout(scout_bts_name_multi):
                return scout_bts_name_multi

        return None

    def _build_hyper_link_to_omnia_and_scout(self):
        links, scout_href, omnia_href = "", None, None
        if self.tl_details['scout_link']:
            scout_href = f"<a href='{self.tl_details['scout_link']}'>SCOUT</a>"
        if self.tl_details['omnia_link']:
            omnia_href = f"<a href='{self.tl_details['omnia_link']}'>OMNIA</a>"

        for href_link in (omnia_href, scout_href):
            if href_link:
                links = links + '|' if links else ''
                links = links + href_link
        if links:
            links = "[{}]".format(links)
        return links


class Message(object):
    """
    Represents an email message.

    Set the To, From, Reply-To, Subject, and Body attributes as plain-text strings.
    Optionally, set the Html attribute to send an HTML email, or use the
    attach() method to attach files.

    Use the charset property to send messages using other than us-ascii

    If you specify an attachments argument, it should be a list of
    attachment filenames: ["file1.txt", "file2.txt"]

    `To` should be a string for a single address, and a sequence
    of strings for multiple recipients (castable to list)

    Send using the Mailer class.
    """

    def __init__(self, **kwargs):
        """
        ***  Copy from mailer.py  ***
        Parameters and default values (parameter names are case insensitive):
            To=None, From=None, RTo=None, CC=None, BCC=None, Subject=None, Body=None, Html=None,
            Date=None, Attachments=None, Charset=None, Headers=None
        """

        # extract  parameters and convert names to lowercase
        params = {}
        for i in kwargs:
            params[i.lower()] = kwargs[i]

        self.To = params.get('to', None)
        self.CC = params.get('cc', None)
        self.From = params.get('from', None)
        self.Subject = params.get('subject', u'')
        self.Body = params.get('body', None)
        self.Html = params.get('html', None)
        self.Date = params.get('date', time.strftime("%a, %d %b %Y %H:%M:%S %z", time.gmtime()))
        self.charset = params.get('charset', 'us-ascii')
        self.attachments = self._preprocess_attachments(params.get('attachments', None))

        if hasattr(self.Body, 'encode'):
            self.Body = self.Body.encode(self.charset)

    def as_string(self):
        """Get the email as a string to send in the mailer"""

        if not self.attachments:
            return self._plaintext()
        else:
            return self._multipart()

    def _plaintext(self):
        """Plain text email with no attachments"""

        if not self.Html:
            msg = MIMEText(self.Body, 'plain', self.charset)
        else:
            msg = self._with_html()

        self._set_info(msg)
        return msg.as_string()

    def _with_html(self):
        """There's an html part"""

        outer = MIMEMultipart('alternative')

        part1 = MIMEText(self.Body, 'plain', self.charset)
        part2 = MIMEText(self.Html, 'html', self.charset)

        outer.attach(part1)
        outer.attach(part2)

        return outer

    def _set_info(self, msg):
        self.prepare_subject_and_from_header(msg)
        self.prepare_to_header(msg)
        self.prepare_cc_header(msg)
        msg['Date'] = self.Date

    def prepare_cc_header(self, msg):
        if self.CC:
            if isinstance(self.CC, str):
                msg['CC'] = self.CC
            else:
                self.CC = list(self.CC)
                msg['CC'] = ", ".join(self.CC)

    def prepare_to_header(self, msg):
        if isinstance(self.To, str):
            msg['To'] = self.To
        else:
            self.To = list(self.To)
            self.To = set(self.To)
            msg['To'] = ", ".join(self.To)

    def prepare_subject_and_from_header(self, msg):
        if self.charset == 'us-ascii':
            msg['Subject'] = self.Subject
            msg['From'] = self.From

        else:
            if hasattr(self.Subject, 'decode'):
                subject = self.Subject.decode(self.charset)
            else:
                subject = self.Subject

            msg['Subject'] = str(make_header([(subject, self.charset)]))  # tu jest konwer do str

            if hasattr(self.From, 'decode'):
                from_ = self.From.decode(self.charset)
            else:
                from_ = self.From

            msg['From'] = str(make_header([(from_, self.charset)]))

    def _multipart(self):
        """The email has attachments"""

        msg = MIMEMultipart('related')

        if self.Html:
            outer = MIMEMultipart('alternative')

            part1 = MIMEText(self.Body, 'plain', self.charset)
            part1.add_header('Content-Disposition', 'inline')

            part2 = MIMEText(self.Html, 'html', self.charset)
            part2.add_header('Content-Disposition', 'inline')

            outer.attach(part1)
            outer.attach(part2)
            msg.attach(outer)
        else:
            msg.attach(MIMEText(self.Body, 'plain', self.charset))

        self._set_info(msg)
        msg.preamble = self.Subject

        for filename, cid, mimetype, content, charset in self.attachments:
            self._add_attachment(msg, filename, cid, mimetype, content, charset)

        return msg.as_string()

    @staticmethod
    def _add_attachment(outer, filename, cid, mimetype, content, charset):
        """
        If mimetype is None, it will try to guess the mimetype
        """
        if mimetype:
            ctype = mimetype
            encoding = None
        else:
            ctype, encoding = mimetypes.guess_type(filename)

        if ctype is None or encoding is not None:
            # No guess could be made, or the file is encoded (compressed), so
            # use a generic bag-of-bits type.
            ctype = 'application/octet-stream'

        maintype, subtype = ctype.split('/', 1)
        if not content:
            with open(filename, 'rb') as fp:
                content = fp.read()

        types = {'text': MIMEText(content, _subtype=subtype, _charset=charset),
                 'image': MIMEImage(content, _subtype=subtype),
                 'audio': MIMEAudio(content, _subtype=subtype)}
        try:
            msg = types[maintype]
        except KeyError:
            msg = MIMEBase(maintype, subtype)
            msg.set_payload(content)
            # Encode the payload using Base64
            encoders.encode_base64(msg)

        # Set the content-ID header
        if cid:
            msg.add_header('Content-ID', '<%s>' % cid)
            msg.add_header('Content-Disposition', 'inline')
        else:
            # Set the filename parameter
            msg.add_header('Content-Disposition', 'attachment', filename=os.path.basename(filename))

        outer.attach(msg)

    def attach(self, filename, cid=None, mimetype=None, content=None, charset=None):
        """
        Attach a file to the email. Specify the name of the file;
        Message will figure out the MIME type and load the file.

        Specify mimetype to set the MIME type manually. The content
        argument take the contents of the file if they are already loaded
        in memory.
        """

        self.attachments.append((filename, cid, mimetype, content, charset))

    @staticmethod
    def _preprocess_attachments(attachments):
        _attachments = []
        if attachments:
            for attachment in attachments:
                Message.prepare_attachment(_attachments, attachment)
        return _attachments

    @staticmethod
    def prepare_attachment(_attachments, attachment):
        if isinstance(attachment, str):
            _attachments.append((attachment, None, None, None, None))
        else:
            try:
                length = len(attachment)
            except TypeError:
                length = None
            else:
                if length is None or length <= 4:
                    _attachments.append((attachment, None, None, None, None))
                else:
                    _attachments.append((tuple(attachment) + (None, None, None, None))[:4])
